theorem thm_GAR : 
  let f : ℝ → ℝ := fun x => |1 - 2*x|
  let m := Int.gcd (Int.gcd (702 - 787) (787 - 855)) (855 - 702)
  let r := 702 % m
  let n := Int.gcd (Int.gcd (412 - 722) (722 - 815)) (815 - 412)  
  let s := 412 % n
  let k := Nat.card {x : ℝ | x ∈ Set.Icc 0 1 ∧ f (f (f x)) = (1/2) * x}
  m + n + r + s + k = 702 + 787 + 855 + 412 + 722 + 815 := by

theorem thm_GAR : 
  let α := Real.arccos (3/5)
  let β := Real.arcsin (3/5)
  let series := ∑' n : ℕ, ∑' m : ℕ, (Real.cos (α * n + β * m)) / (2^n * 3^m)
  ∃ (A B : ℕ), 
    series = (A : ℝ) / (B : ℝ) ∧ 
    Nat.gcd A B = 1 ∧
    A > 0 ∧ B > 0 ∧
    (∀ x y : ℤ, x^5 + 3*x^4*y - 5*x^3*y^2 - 15*x^2*y^3 + 4*x*y^4 + 12*y^5 ≠ 33) ∧
    1000 * A + B = 2000000 := by

theorem thm_GAR : ∃ (θ : ℝ), 
  let S := ∑ k in Finset.range 44, 
    (if k % 4 = 0 then Real.cos ((2 * (k + 1)) * Real.pi / 180)
     else if k % 4 = 1 then -Real.sin ((2 * (k + 1)) * Real.pi / 180)
     else if k % 4 = 2 then -Real.cos ((2 * (k + 1)) * Real.pi / 180)
     else Real.sin ((2 * (k + 1)) * Real.pi / 180))
  ∀ x : ℝ, 6 * x^2 - x - 2 ≠ 0 → 
    S / (6 * x^2 - x - 2) = (1 / Real.cos θ) - Real.tan θ := by

